SELECT EXISTS (SELECT 1 FROM users
WHERE id = #{id}
AND deleted = false
)

SELECT EXISTS (SELECT 1 FROM users
WHERE name= #{name}
AND id != #{id}
AND deleted = false
)

SELECT EXISTS (SELECT 1 FROM users
WHERE mail= #{mail}
AND id != #{id}
AND deleted = false
)

